function openCommand() {
  modal('Search your workspace','<label class="search-field command-field">'+icon('search')+'<input id="command-input" placeholder="Search pages, documents or actions…" aria-label="Search pages, documents or actions" autocomplete="off"></label><div id="command-results">'+commandResults('')+'</div>');
  $('#command-input').focus();
}
function commandResults(query) {
  const q=query.trim().toLowerCase();
  const pages=nav.concat([['ask','search','Questions about records']]).filter(n=>n[2].toLowerCase().includes(q));
  const docs=typeof allRecords==='function'&&q?allRecords().filter(d=>(d.title+' '+d.category).toLowerCase().includes(q)).slice(0,5):[];
  const actionList=q?tasks.filter(t=>t.title.toLowerCase().includes(q)).slice(0,4):[];
  return (pages.length?'<div class="command-section">PAGES</div>'+pages.map(n=>'<button class="command-result" data-action="command-go" data-route="'+n[0]+'">'+icon(n[1])+'<span>'+n[2]+'</span>'+icon('arrow')+'</button>').join(''):'')+(docs.length?'<div class="command-section">DOCUMENTS</div>'+docs.map(d=>'<button class="command-result" data-action="document" data-id="'+d.id+'">'+icon('files')+'<span>'+escapeHTML(d.title)+'</span></button>').join(''):'')+(actionList.length?'<div class="command-section">ACTIONS</div>'+actionList.map(t=>'<button class="command-result" data-task="'+t.id+'">'+icon('plan')+'<span>'+escapeHTML(t.title)+'</span></button>').join(''):'')||'<div class="empty-state"><h2>No matches</h2><p>Try a document name or “insurance”.</p></div>';
}
window.actions['command-go']=a=>{$('#detail-dialog').close();go(a.dataset.route)};
document.addEventListener('input',e=>{if(e.target.id==='command-input')$('#command-results').innerHTML=commandResults(e.target.value)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}});
render();
